function aplicarFiltros(personas: PersonaTallaCuota[], filtros: Filtros) {
  const texto = filtros.buscar.trim().toLocaleLowerCase("es");
  return personas.filter((p) => {
    const coincideTexto = !texto || `${p.nombre} ${p.ci} ${p.codigoFraterno} ${p.telefono}`.toLocaleLowerCase("es").includes(texto);
    const coincideSexo = filtros.sexo === "TODOS" || p.sexo === filtros.sexo;
    const coincideTalla = filtros.talla === "TODOS" || p.estadoMedicion === filtros.talla;
    const coincidePrenda = filtros.prenda === "TODAS" || (filtros.prenda === "POLERA" ? p.tienePolera : p.tieneChamarra);
    const coincideTallaValor = filtros.tallaValor === "TODAS" || (filtros.prenda === "POLERA" ? p.tallaPolera === filtros.tallaValor : filtros.prenda === "CHAMARRA" ? p.tallaChamarra === filtros.tallaValor : p.tallaPolera === filtros.tallaValor || p.tallaChamarra === filtros.tallaValor);
    const coincidePago = filtros.pago === "TODOS" || p.estadoPagoReporte === filtros.pago || (filtros.pago === "PAGO VERIFICADO" && p.montoVerificadoTotal > 0);
    const coincideVerificacion = filtros.verificacion === "TODOS" || p.estadoVerificacionPago === filtros.verificacion || (filtros.verificacion === "PENDIENTE" && p.estadoVerificacionPago === "PENDIENTE DE VERIFICACIÓN");
    const coincideEstado = filtros.estado === "TODOS" || (p.perfilFraterno && ((filtros.estado === "SIN_TALLA" && !p.conTalla) || (filtros.estado === "SIN_PRIMERA" && p.primeraCuota === "PENDIENTE") || (filtros.estado === "AMBOS" && !p.conTalla && p.primeraCuota === "PENDIENTE")));
    const coincideRol = filtros.rol === "TODOS" || p.roles.includes(filtros.rol);
    const coincideBloque = filtros.bloque === "TODOS" || p.bloque === filtros.bloque;
    return coincideTexto && coincideSexo && coincideTalla && coincidePrenda && coincideTallaValor && coincidePago && coincideVerificacion && coincideEstado && coincideRol && coincideBloque;
  });
}

