  listado("TODOS LOS USUARIOS", personas); listado("USUARIOS CON TALLA", personas.filter((p) => p.tienePolera || p.tieneChamarra)); listado("USUARIOS SIN TALLA", personas.filter((p) => !p.tienePolera && !p.tieneChamarra)); listado("POLERAS HOMBRES", personas.filter((p) => p.sexo === "HOMBRE" && p.tienePolera)); listado("POLERAS MUJERES", personas.filter((p) => p.sexo === "MUJER" && p.tienePolera)); listado("CHAMARRAS HOMBRES", personas.filter((p) => p.sexo === "HOMBRE" && p.tieneChamarra)); listado("CHAMARRAS MUJERES", personas.filter((p) => p.sexo === "MUJER" && p.tieneChamarra));
