function Metrica({titulo,valor}:{titulo:string;valor:number}) { return <div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{titulo}</p><b className="text-2xl text-[#74122A]">{valor}</b></div>; }
function ResumenGenero({titulo,resumen}:{titulo:string;resumen:ResumenTallaCuota}) { return <div className="rounded-xl border p-4"><h3 className="font-black text-[#74122A]">{titulo}</h3><div className="mt-2 grid grid-cols-2 gap-2 text-sm"><span>Total: <b>{resumen.total}</b></span><span>Con talla: <b>{resumen.conTalla}</b></span><span>Sin talla: <b>{resumen.sinTalla}</b></span><span>Con talla sin pago: <b>{resumen.conTallaSinPago}</b></span><span>Pago por verificar: <b>{resumen.conTallaPagoPendiente}</b></span><span>Pago verificado: <b>{resumen.conTallaPagoVerificado}</b></span><span>Pago parcial: <b>{resumen.conTallaPagoParcial}</b></span><span>Pago completo: <b>{resumen.conTallaPagoCompleto}</b></span></div></div>; }
function TablaTallasPagos({ titulo, personas }: { titulo: string; personas: PersonaTallaCuota[] }) { return <section className="rounded-2xl border p-4"><h3 className="mb-3 text-lg font-black uppercase text-[#74122A]">{titulo} ({personas.length})</h3><div className="max-h-96 overflow-auto"><table className="min-w-[1800px] w-full text-xs"><thead className="sticky top-0"><tr>{columnasTallasPagos.map((columna) => <th key={columna} className="border bg-slate-100 p-2 text-left">{columna}</th>)}</tr></thead><tbody>{personas.map((persona, indice) => <tr key={persona.usuarioId}>{filaTallasPagos(persona, indice).map((valor, posicion) => <td key={columnasTallasPagos[posicion]} className="border p-2">{String(valor)}</td>)}</tr>)}</tbody></table></div></section>; }
function Select({valor,cambiar,opciones}:{valor:string;cambiar:(v:string)=>void;opciones:string[][]}) { return <select value={valor} onChange={(e) => cambiar(e.target.value)} className="rounded-xl border p-3">{opciones.map(([v,t]) => <option key={v} value={v}>{t}</option>)}</select>; }
function DetalleSinDefinir({ personas, resumen }: { personas: PersonaTallaCuota[]; resumen: { personasUnicas: number; camposPrenda: number } }) {
  return <section className="mt-4 space-y-3"><p className="text-sm text-slate-700">Se conserva y muestra el valor real almacenado. No se corrige automáticamente.</p><div className="grid grid-cols-2 gap-3"><Metrica titulo="Personas únicas" valor={resumen.personasUnicas}/><Metrica titulo="Campos afectados" valor={resumen.camposPrenda}/></div><div className="max-h-80 overflow-auto"><table className="w-full min-w-[1100px] text-xs"><thead className="sticky top-0"><tr>{["Nombre", "CI", "Sexo", "Rol", "Bloque", "Valor real tallaPolera", "Estado polera", "Valor real tallaChamarra", "Estado chamarra"].map((titulo) => <th key={titulo} className="border bg-red-800 p-2 text-left text-white">{titulo}</th>)}</tr></thead><tbody>{personas.map((persona) => <tr key={persona.usuarioId}><td className="border p-2 font-bold">{persona.nombre}</td><td className="border p-2">{persona.ci}</td><td className="border p-2">{persona.sexo}</td><td className="border p-2">{persona.roles.join(" / ") || "SIN ROL"}</td><td className="border p-2">{persona.bloque}</td><td className="border p-2 font-mono">{persona.tallaPolera === null ? "<null>" : JSON.stringify(persona.tallaPolera)}</td><td className="border p-2">{persona.estadoCampoPolera}</td><td className="border p-2 font-mono">{persona.tallaChamarra === null ? "<null>" : JSON.stringify(persona.tallaChamarra)}</td><td className="border p-2">{persona.estadoCampoChamarra}</td></tr>)}</tbody></table></div></section>;
}
function DetalleSinTalla({ personas, bloques }: { personas: PersonaTallaCuota[]; bloques: string[] }) {
  personas = personas.filter((persona) => persona.estadoCampoPolera !== "SIN DEFINIR" && persona.estadoCampoChamarra !== "SIN DEFINIR");
  const [sexo, setSexo] = useState("TODOS"), [rol, setRol] = useState("TODOS"), [pago, setPago] = useState("TODOS"), [faltante, setFaltante] = useState("TODOS"), [bloque, setBloque] = useState("TODOS");
  const roles = [...new Set(personas.flatMap((persona) => persona.roles))].sort();
  const filtradas = personas.filter((persona) => (sexo === "TODOS" || persona.sexo === sexo) && (rol === "TODOS" || persona.roles.includes(rol)) && (bloque === "TODOS" || persona.bloque === bloque) && (faltante === "TODOS" || persona.pendienteTalla === faltante) && (pago === "TODOS" || persona.estadoPagoReporte === pago || (pago === "PRIMERA CUOTA VERIFICADA" && persona.verificacionPrimeraCuota === "VERIFICADO") || (pago === "RECHAZADO" && persona.estadoVerificacionPago === "RECHAZADO")));
  const hombres = personas.filter((persona) => persona.sexo === "HOMBRE"), mujeres = personas.filter((persona) => persona.sexo === "MUJER");
  const conteo = (lista: PersonaTallaCuota[], criterio: (persona: PersonaTallaCuota) => boolean) => lista.filter(criterio).length;
  const porRoles = roles.map((nombre) => { const lista = personas.filter((persona) => persona.roles.includes(nombre)); return { nombre, hombres: conteo(lista, (p) => p.sexo === "HOMBRE"), mujeres: conteo(lista, (p) => p.sexo === "MUJER"), sinPago: conteo(lista, (p) => p.estadoPagoReporte === "SIN PAGO"), pendiente: conteo(lista, (p) => p.estadoPagoReporte === "PENDIENTE DE VERIFICACIÓN"), verificada: conteo(lista, (p) => p.verificacionPrimeraCuota === "VERIFICADO") }; });
  return <section className="mt-6 space-y-5 rounded-2xl border-2 border-amber-300 bg-amber-50/40 p-4">
    <div><h3 className="text-xl font-black text-[#74122A]">USUARIOS SIN TALLA O CON MEDICIÓN INCOMPLETA</h3><p className="text-sm text-slate-600">Cada persona aparece una sola vez. Los totales por prenda pueden coincidir cuando faltan ambas tallas.</p></div>
    <div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Metrica titulo="Total incompletos" valor={personas.length}/><Metrica titulo="Sin ninguna talla" valor={conteo(personas, (p) => p.pendienteTalla === "AMBAS")}/><Metrica titulo="Solo falta polera" valor={conteo(personas, (p) => p.pendienteTalla === "POLERA")}/><Metrica titulo="Solo falta chamarra" valor={conteo(personas, (p) => p.pendienteTalla === "CHAMARRA")}/><Metrica titulo="Sin primera cuota" valor={conteo(personas, (p) => p.estadoPagoReporte === "SIN PAGO")}/><Metrica titulo="Pago pendiente" valor={conteo(personas, (p) => p.estadoPagoReporte === "PENDIENTE DE VERIFICACIÓN")}/><Metrica titulo="Primera cuota verificada" valor={conteo(personas, (p) => p.verificacionPrimeraCuota === "VERIFICADO")}/><Metrica titulo="Pago parcial" valor={conteo(personas, (p) => p.estadoPagoReporte === "PAGO PARCIAL")}/></div>
    <div className="grid gap-3 md:grid-cols-2"><ResumenFaltantes titulo="Hombres" personas={hombres}/><ResumenFaltantes titulo="Mujeres" personas={mujeres}/></div>
    <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-xs"><thead><tr>{["Rol", "Hombres", "Mujeres", "Sin pago", "Pendiente verificación", "Primera cuota verificada"].map((titulo) => <th key={titulo} className="border bg-[#74122A] p-2 text-left text-white">{titulo}</th>)}</tr></thead><tbody>{porRoles.map((fila) => <tr key={fila.nombre}><td className="border p-2 font-bold">{fila.nombre}</td><td className="border p-2">{fila.hombres}</td><td className="border p-2">{fila.mujeres}</td><td className="border p-2">{fila.sinPago}</td><td className="border p-2">{fila.pendiente}</td><td className="border p-2">{fila.verificada}</td></tr>)}</tbody></table></div>
    <div className="grid gap-2 md:grid-cols-3 xl:grid-cols-5"><Select valor={sexo} cambiar={setSexo} opciones={[["TODOS", "Sexo: todos"], ["HOMBRE", "Hombres"], ["MUJER", "Mujeres"]]}/><Select valor={rol} cambiar={setRol} opciones={[["TODOS", "Rol: todos"], ...roles.map((valor) => [valor, valor])]}/><Select valor={pago} cambiar={setPago} opciones={[["TODOS", "Pago: todos"], ["SIN PAGO", "Sin pago"], ["PENDIENTE DE VERIFICACIÓN", "Pendiente de verificación"], ["PRIMERA CUOTA VERIFICADA", "Primera cuota verificada"], ["PAGO PARCIAL", "Pago parcial"], ["PAGO COMPLETO", "Pago completo"], ["RECHAZADO", "Rechazado"]]}/><Select valor={faltante} cambiar={setFaltante} opciones={[["TODOS", "Talla faltante: todas"], ["POLERA", "Polera"], ["CHAMARRA", "Chamarra"], ["AMBAS", "Ambas"]]}/><Select valor={bloque} cambiar={setBloque} opciones={[["TODOS", "Bloque: todos"], ...bloques.map((valor) => [valor, valor])]}/></div>
    <p className="font-bold text-[#74122A]">{filtradas.length} persona(s) encontradas</p>
    <div className="max-h-[32rem] overflow-auto"><table className="min-w-[2400px] w-full text-xs"><thead className="sticky top-0"><tr>{columnasSinTalla.map((titulo) => <th key={titulo} className="border bg-slate-100 p-2 text-left">{titulo}</th>)}</tr></thead><tbody>{filtradas.map((persona, indice) => <tr key={persona.usuarioId}>{filaSinTalla(persona, indice).map((valor, posicion) => <td key={columnasSinTalla[posicion]} className="border p-2">{posicion === 5 && persona.whatsapp ? <a href={`https://wa.me/${persona.whatsapp.replace("+", "")}`} target="_blank" rel="noreferrer" className="font-bold text-emerald-700 underline">{String(valor)}</a> : String(valor)}</td>)}</tr>)}</tbody></table></div>
  </section>;
}
function ResumenFaltantes({ titulo, personas }: { titulo: string; personas: PersonaTallaCuota[] }) { return <div className="rounded-xl border bg-white p-4"><h4 className="font-black text-[#74122A]">{titulo}</h4><div className="mt-2 grid grid-cols-2 gap-2 text-sm"><span>Sin polera: <b>{personas.filter((p) => !p.tienePolera).length}</b></span><span>Sin chamarra: <b>{personas.filter((p) => !p.tieneChamarra).length}</b></span><span>Sin ninguna: <b>{personas.filter((p) => p.pendienteTalla === "AMBAS").length}</b></span><span>Incompleta: <b>{personas.filter((p) => p.pendienteTalla !== "AMBAS").length}</b></span></div></div>; }
function ListadoEspecial({ titulo, personas, tipo }: { titulo: string; personas: PersonaTallaCuota[]; tipo: "CUOTA" | "MEDICION" | "POSTULANTE" }) {
  const hombres = personas.filter((p) => p.sexo === "HOMBRE").length, mujeres = personas.filter((p) => p.sexo === "MUJER").length;
  const incompletos = personas.filter((p) => p.pendienteTalla !== "AMBAS").length;
  return <div className="rounded-2xl border p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-black text-[#74122A]">{titulo}</h3><p className="text-sm text-slate-600">Total: <b>{personas.length}</b> · Hombres: <b>{hombres}</b> · Mujeres: <b>{mujeres}</b>{tipo === "MEDICION" && <> · Medición incompleta: <b>{incompletos}</b></>}</p></div><button onClick={() => void exportarListado(titulo, personas, tipo)} className="rounded-xl bg-emerald-700 px-4 py-2 font-bold text-white">Exportar Excel</button></div><div className="mt-3 max-h-72 overflow-auto"><table className="w-full min-w-[1200px] text-xs"><thead><tr>{["Nombre", "CI", "Sexo", "Teléfono", "WhatsApp", "Roles", "Asignación", "Bloque", "Monto", "Registrado", "Verificado", "Saldo", "Estado", "Verificación", "Tallas"].map((c) => <th key={c} className="border bg-slate-100 p-2 text-left">{c}</th>)}</tr></thead><tbody>{personas.map((p) => <tr key={p.usuarioId}><td className="border p-2 font-bold">{p.nombre}</td><td className="border p-2">{p.ci}</td><td className="border p-2">{p.sexo}</td><td className="border p-2">{p.telefono}</td><td className="border p-2">{p.whatsapp ?? ""}</td><td className="border p-2">{p.roles.join(" / ")}</td><td className="border p-2">{p.asignacion}</td><td className="border p-2">{p.bloque}</td><td className="border p-2">Bs {p.montoPrimeraCuota.toFixed(2)}</td><td className="border p-2">Bs {p.montoRegistradoPrimeraCuota.toFixed(2)}</td><td className="border p-2">Bs {p.montoVerificadoPrimeraCuota.toFixed(2)}</td><td className="border p-2">Bs {p.saldoPrimeraCuota.toFixed(2)}</td><td className="border p-2">{p.estadoPago}</td><td className="border p-2">{p.verificacionPrimeraCuota}</td><td className="border p-2">{p.pendienteTalla === "AMBAS" ? "SIN MEDICIÓN" : p.pendienteTalla ? "INCOMPLETA" : "COMPLETA"}</td></tr>)}</tbody></table></div></div>;
}
function TarjetaListado({ titulo, descripcion, abierto, alternar, cargando, error, personas, tipo }: { titulo: string; descripcion: string; abierto: boolean; alternar: () => void; cargando: boolean; error?: string; personas: PersonaTallaCuota[]; tipo: "CUOTA" | "MEDICION" | "POSTULANTE" }) {
  return <section className="rounded-2xl border border-[#74122A]/20 bg-white p-5 shadow-sm"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h2 className="text-xl font-black text-[#74122A]">{titulo}</h2><p className="text-sm text-slate-600">{descripcion}</p></div><button onClick={alternar} className="rounded-xl bg-[#74122A] px-5 py-3 font-black text-white">{abierto ? "OCULTAR REPORTE" : "VER REPORTE"}</button></div>{abierto && <div className="mt-5">{cargando ? <p>Cargando reporte…</p> : error ? <p className="text-red-700">{error}</p> : <ListadoEspecial titulo={titulo} personas={personas} tipo={tipo}/>}</div>}</section>;
}
